import{_ as n,o as s,c as r,a3 as o}from"./chunks/framework.z_KJ15Ep.js";const t="/bilder/vorbereitung/gruppenprozesse-abgeschlossene-facher-loeschen-1.png",i="/bilder/vorbereitung/gruppenprozesse-abgeschlossene-facher-loeschen-2.png",m=JSON.parse('{"title":"Übernommene abgeschlossene Fächer entfernen","description":"","frontmatter":{"title":"Übernommene abgeschlossene Fächer entfernen","source_pageid":801,"source_revision":5411},"headers":[],"relativePath":"zeugnisse/vorbereitung/abgeschlossene-faecher-loeschen-gruppenprozesse-noten-zeugnisvorbereitung.md","filePath":"zeugnisse/vorbereitung/abgeschlossene-faecher-loeschen-gruppenprozesse-noten-zeugnisvorbereitung.md"}'),c={name:"zeugnisse/vorbereitung/abgeschlossene-faecher-loeschen-gruppenprozesse-noten-zeugnisvorbereitung.md"};function h(l,e,a,p,g,u){return s(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="ubernommene-abgeschlossene-facher-entfernen" tabindex="-1">Übernommene abgeschlossene Fächer entfernen <a class="header-anchor" href="#ubernommene-abgeschlossene-facher-entfernen" aria-label="Permalink to &quot;Übernommene abgeschlossene Fächer entfernen&quot;">​</a></h1><p>Entfernen Sie die zusätzlich übernommenen abgeschlossenen Fächer beziehungsweise Noten aus dem aktiven Abschnitt. Die Anleitung nennt auch den Weg für einzelne Datensätze.</p><p><a href="/bilder/vorbereitung/gruppenprozesse-abgeschlossene-facher-loeschen-1.png"><img src="'+t+'" alt="Abgeschlossene Fächer per Gruppenprozess für gefilterte Schülergruppen verarbeiten." loading="lazy"></a></p><p><em>Abgeschlossene Fächer per Gruppenprozess für gefilterte Schülergruppen verarbeiten.</em></p><p>Dieser Gruppenprozess dient dem Löschen der über <em>&quot;Abgeschlossene Fächer holen&quot;</em> zusätzlich eingetragenen abgeschlossenen Fächer - beziehungsweise deren Noten.</p><p>Der Gruppenprozess löscht diese Fächer im aktiven Abschnitt (Halbjahr).</p><p><a href="/bilder/vorbereitung/gruppenprozesse-abgeschlossene-facher-loeschen-2.png"><img src="'+i+'" alt="Bei einzelnen Schülern abgeschlossene Fächer bearbeiten (&quot;holen&quot; oder &quot;löschen&quot;)" loading="lazy"></a></p><p><em>Bei einzelnen Schülern abgeschlossene Fächer bearbeiten (&quot;holen&quot; oder &quot;löschen&quot;)</em></p><p>.</p><p>Für eine einzelne Person öffnen Sie <strong>Schüler → Übersicht</strong>. Klicken Sie mit der rechten Maustaste in die letzte Spalte. Dort stehen zwei Löschmöglichkeiten zur Verfügung:</p><ul><li><em>Abgeschlossene Fächer löschen</em></li><li><em>Einzelnes abgeschlossenes Fach löschen</em></li></ul><p>Weiterhin können über dieses Kontextmenü abgeschlossene Fächer geholt werden.</p><hr><p><a href="https://schulverwaltungsinfos.nrw.de/svws/wiki/index.php?title=Abgeschlossene_F%C3%A4cher_l%C3%B6schen_(Gruppenprozesse_Noten,_Zeugnisvorbereitung)" target="_blank" rel="noreferrer">Originalartikel im Wiki</a> · Quellrevision 5411.</p>',14)])])}const f=n(c,[["render",h]]);export{m as __pageData,f as default};
